import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Piwork","text":"A shareable, runnable AI workspace","tagline":"Powered by an evolvable Harness.","image":{"src":"/logo.png","alt":"Piwork"},"actions":[{"theme":"brand","text":"Get Started","link":"/guide/quick-start"},{"theme":"alt","text":"GitHub","link":"https://github.com/pphboy/piwork"},{"theme":"alt","text":"Discussions","link":"https://github.com/pphboy/piwork/discussions"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function i(s,e,d,l,p,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="what-is-piwork" tabindex="-1">What is Piwork? <a class="header-anchor" href="#what-is-piwork" aria-label="Permalink to &quot;What is Piwork?&quot;">​</a></h2><p>Piwork packages a runnable AI workspace into a portable unit called a <strong>Work</strong>. Keep the applications, files, conversation history, and execution environment together, then export them and continue on another Piwork installation.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Role</th></tr></thead><tbody><tr><td><a href="/piwork/concepts/work.html">Work</a></td><td><strong>The workspace.</strong> Holds the environment and its durable state.</td></tr><tr><td><a href="/piwork/concepts/service.html">Service</a></td><td><strong>The capability.</strong> Runs an application, API, or other container service.</td></tr><tr><td><a href="/piwork/concepts/harness.html">Harness</a></td><td><strong>The intelligence.</strong> Uses models, tools, and workspace-specific instructions to understand and operate the Work.</td></tr></tbody></table><p>The Harness can help build and change the workspace it runs in. Its instructions, Skills, packages, and verified experience can evolve with that Work.</p><p>Default Web development uses a reusable FastAPI + React + TypeScript + Vite environment. Standard templates adopt deployed updates automatically; see <a href="/piwork/guide/web-development.html">Web Development</a> for usage and maintenance.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><strong>Create → Run → Evolve → Export → Share → Import → Continue</strong></p><p>Export a stopped Work as a <code>.work</code> file. Import it into a compatible installation and start it explicitly. The target supplies its own model credentials.</p><h2 id="demo-kanban-work" tabindex="-1">Demo: Kanban Work <a class="header-anchor" href="#demo-kanban-work" aria-label="Permalink to &quot;Demo: Kanban Work&quot;">​</a></h2><p>A board, its data, an application Service, and a Harness that helps build and operate it form one workspace. <a href="/piwork/demo/kanban.html">Read the Kanban walkthrough</a>. A downloadable demo and recording are still being prepared.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><p><a href="/piwork/guide/quick-start.html">Try Core and CLI in the terminal</a>: use the existing initialization environment, one Docker command per entry, or deploy Core alone using <a href="/piwork/piwork/install/0.0.2-fb4f577da3b4-512ec778b267/docker-compose.yml">docker-compose.yml</a>. Log in, create a Work and receive the first reply. Piwork 0.0.2 Preview images are published and anonymously verified.</p><p>Native CLI remains a folded Quick Start alternative. See <a href="/piwork/guide/installation.html#core-compose-demo">Installation</a> for the advanced Core-only Demo.</p>',13)])])}const m=t(n,[["render",i]]);export{k as __pageData,m as default};
